// ../lib/visits.mjs
function emptyVisits() {
  return { version: 1, towns: { munich: { id: "munich", knownHome: true, firstDay: null, firstSeenAt: null, daysVisited: [], reason: "\u5DF2\u77E5\u5C45\u6240\uFF0C\u4E0D\u5C07\u8FD4\u5BB6\u7576\u6210\u7B2C\u4E00\u6B21\u53BB\u6155\u5C3C\u9ED1" } }, landmarks: {} };
}
var dayOf = (t) => new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Berlin", year: "numeric", month: "2-digit", day: "2-digit" }).format(t);
function markTown(registry, id, time) {
  if (!registry.towns[id]) registry.towns[id] = { id, firstSeenAt: time, firstDay: dayOf(time), daysVisited: [] };
  const r = registry.towns[id], day = dayOf(time);
  if (!r.daysVisited.includes(day)) r.daysVisited.push(day);
  r.lastSeenAt = Math.max(r.lastSeenAt || time, time);
  return r;
}
function markLandmark(registry, location, time, place) {
  const p = place?.topicId ? { id: place.topicId, name: place.name } : landmarks[location];
  if (!p) return;
  if (!place?.topicId || place.withinTown) markTown(registry, location, time);
  if (!registry.landmarks[p.id]) registry.landmarks[p.id] = { id: p.id, town: location, name: p.name, topicId: place?.topicId, source: place?.source, firstSeenAt: time, firstDay: dayOf(time), daysVisited: [] };
  const r = registry.landmarks[p.id], day = dayOf(time);
  if (!r.daysVisited.includes(day)) r.daysVisited.push(day);
  r.lastSeenAt = Math.max(r.lastSeenAt || time, time);
  return r;
}
function visitsFromHistory(events = []) {
  const r = emptyVisits();
  for (const e of [...events].sort((a, b) => a.time - b.time)) {
    if (!Number.isFinite(e.time)) continue;
    if (e.type === "accepted") markTown(r, e.from, e.time);
    if (e.type === "delivered") markTown(r, e.to, e.time);
    if (e.type === "visit" && !e.place?.generic) markLandmark(r, e.location, e.time, e.place);
    if (["home_arrived", "home_day"].includes(e.type)) markTown(r, "munich", e.time);
  }
  return r;
}
function discoveriesForDay(registry, day) {
  return { towns: Object.values(registry.towns).filter((r) => !r.knownHome && r.firstDay === day).sort((a, b) => a.firstSeenAt - b.firstSeenAt), landmarks: Object.values(registry.landmarks).filter((r) => r.firstDay === day).sort((a, b) => a.firstSeenAt - b.firstSeenAt) };
}
