        extras.ja.push(`\u3053\u306E\u65C5\u3067\u521D\u3081\u3066${c.ja}\u306B\u6765\u307E\u3057\u305F\u3002${c.region}\u306B\u3042\u308B\u753A\u3067\u3059\u3002\u30CE\u30FC\u30C8\u306B\u753A\u306E\u540D\u524D\u3092\u66F8\u304D\u307E\u3059\u3002\u307E\u305A\u8FD1\u304F\u306E\u9053\u3092\u899A\u3048\u305F\u3044\u3067\u3059\u3002`);
