  const scene = chooseNovel(scenes.map((row2, i) => ({ id: row2[0], row: row2, i })), history, "scene", seed, 5);
  const focus = focusOf(records, history, seed >>> 4), body = focusText(focus, current), trips = records.filter((e) => e.type === "delivered"), visit = records.find((e) => e.type === "visit");
