      const old = { zh: "\u5361\u8ECA\u9084\u7559\u5728\u53E6\u4E00\u5EA7\u57CE\u5E02", en: "My truck is in another city.", de: "Mein Lkw steht in einer anderen Stadt.", ja: "\u30C8\u30E9\u30C3\u30AF\u306F\u307B\u304B\u306E\u753A\u306B\u3042\u308A\u307E\u3059\u3002" }[lang], replacement = { zh: "\u5361\u8ECA\u4E5F\u505C\u5728\u6155\u5C3C\u9ED1", en: "My truck is in Munich too.", de: "Mein Lkw steht auch in M\xFCnchen.", ja: "\u30C8\u30E9\u30C3\u30AF\u3082\u30DF\u30E5\u30F3\u30D8\u30F3\u306B\u3042\u308A\u307E\u3059\u3002" }[lang];
